package vn.eduassistant.backend.service;

import org.springframework.stereotype.Service;
import vn.eduassistant.backend.core.Json;
import java.time.Instant;
import java.util.*;

@Service
public class VerifyHarnessService {
    private final RuleEngineService rules;private final AddressService addresses;
    public VerifyHarnessService(RuleEngineService rules,AddressService addresses){this.rules=rules;this.addresses=addresses;}
    public Map<String,Object> run(){String runId="verify-"+UUID.randomUUID().toString().substring(0,8),timestamp=Instant.now().toString();List<Map<String,Object>>results=new ArrayList<Map<String,Object>>();String[] ids={"HARNESS-01-ROUTINE-PASS","HARNESS-02-FORMAT-ONLY-PASS","HARNESS-03-FACT-UNKNOWN","HARNESS-04-TEMPORARY-ADDRESS","HARNESS-05-ADDRESS-CONFLICT","HARNESS-06-AUTHORITY-REQUIRED","HARNESS-07-POLICY-OUT-OF-SCOPE","HARNESS-08-OWNERSHIP-UNCLEAR","HARNESS-09-NON-LIVE-FAILSAFE"};String[] expected={"AUTO_APPROVE","AUTO_APPROVE","ESCALATE_TO_HUMAN","ESCALATE_TO_HUMAN","ESCALATE_TO_HUMAN","ESCALATE_TO_HUMAN","ESCALATE_TO_HUMAN","ESCALATE_TO_HUMAN","ESCALATE_TO_HUMAN"};String[] reasons={null,null,"FACT_UNKNOWN","DATA_CONFLICT","DATA_CONFLICT","AUTHORITY_REQUIRED","POLICY_OUT_OF_SCOPE","OWNERSHIP_UNCLEAR","FACT_UNKNOWN"};String address="123 Đường Lê Lợi, Phường Bến Nghé, Quận 1, TP. Hồ Chí Minh";for(int i=0;i<ids.length;i++){long t=System.currentTimeMillis();Map<String,Object> facts=UserService.map("studentId","test-1","studentCode","SV2026-1001","fullName","Nguyễn Văn An","academicStatus",i==5?"SUSPENDED":"ACTIVE","courseStartDate","2022-09-05","courseEndDate","2027-06-30","currentTermActive",true,"hasCurrentSchedule",true,"registeredPermanentAddress",i==4?"9 Đường Lê Lợi, Phường Bến Nghé, Quận 1, TP. Hồ Chí Minh":address,"sourceType","SYNTHETIC_TEST_SIS","verificationStatus","TEST_VERIFIED","recordStatus","ACTIVE");String raw=i==1?"123 le loi, p ben nghe, q1, tphcm":i==2?"123 Đường Lê Lợi, Quận 1, TP. Hồ Chí Minh":address;Map<String,Object> claim=UserService.map("addressType",i==3?"TEMPORARY":"PERMANENT","rawAddress",raw,"declaredAddress",raw,"requestReason",i==6?"Xin cứu xét ngoại lệ ngoài quy trình": "Cấp giấy xác nhận NVQS","notes","");Map<String,Object> ai=addresses.parse(raw);if(i!=2){ai.put("houseNumber","123");ai.put("street","Đường Lê Lợi");ai.put("wardCommune","Phường Bến Nghé");ai.put("provinceCity","TP. Hồ Chí Minh");ai.put("missingFields",Collections.emptyList());ai.put("normalizedAddress",address);ai.put("confidence",.98);}Map<String,Object> meta=UserService.map("modeUsed",i==8?"mock":"fixture","isLive",false,"isFallback",i==8,"fallbackOccurred",i==8,"isSynthetic",true,"provider","FIXED_TEST_FIXTURE","apiCallPerformed",false);Map<String,Object> data=UserService.map("studentId","test-1","studentName",i==7?"Nguyễn Văn Bình":"Nguyễn Văn An","studentCode",i==7?"SV2026-2002":"SV2026-1001","description",raw,"studentClaim",claim,"institutionalFacts",facts,"authoritativeInstitutionalFacts",facts,"addressAnalysis",ai,"aiMetadata",meta);Map<String,Object> ctx=UserService.map("evaluationMode","DETERMINISTIC_TEST","allowSyntheticVerifiedInstitutionalFacts",true,"allowSyntheticAIAnalysis",true);Map<String,Object> verdict=rules.evaluate(data,null,UserService.map("id","test-1","fullName","Nguyễn Văn An","studentCode","SV2026-1001"),meta,ctx);String actual=Json.str(verdict.get("decision")),actualReason=Json.str(verdict.get("escalationReason"));boolean pass=expected[i].equals(actual)&&(reasons[i]==null?verdict.get("escalationReason")==null:reasons[i].equals(actualReason));results.add(UserService.map("caseId",ids[i],"caseName",ids[i].replace('-',' '),"expectedDecision",expected[i],"actualDecision",actual,"expectedReason",reasons[i],"actualReason",verdict.get("escalationReason"),"ruleMatched",verdict.get("ruleMatched"),"institutionalTrust",verdict.get("institutionalTrust"),"explanation",verdict.get("explanation"),"confidence",verdict.get("confidence"),"pass",pass,"durationMs",System.currentTimeMillis()-t));}
        int passed=0;for(Map<String,Object>r:results)if(Json.bool(r.get("pass")))passed++;return UserService.map("runId",runId,"timestamp",timestamp,"durationMs",results.size(),"networkCallsPerformed",false,"databaseCallsPerformed",false,"databaseWritesPerformed",false,"aiCallsPerformed",false,"disclaimer","Deterministic Rule Engine Verification - Không gọi Gemini Live trong các fixture này.","verificationType","DETERMINISTIC_RULE_ENGINE","total",results.size(),"passed",passed,"failed",results.size()-passed,"status",passed==results.size()?"ALL_PASSED":"HAS_FAILURES","results",results);}
}
